import sys

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n, q = map(int, sys.stdin.readline().split())
        if q == n:
            print(0)
        else:
            option1 = n * (n - 1) // 2 - q * (q - 1) // 2
            option2 = (n - q + 1) * (q - 1)
            print(min(option1, option2))

main()
